import { pick, zipObject, unzip } from 'es-toolkit';
import { sumBy } from 'es-toolkit';
export interface Row { id: number; name: string; age: number; }
export type Config = Record<string, unknown>;
export function publicFields(row: Row): Pick<Row, 'id' | 'name'> { return pick(row, ['id', 'name']); }
export function totalAge(rows: Row[]): number { return sumBy(rows, r => r.age); }
